package globlite

import (
	"errors"
)

const maxAlternatives = 256

var errPattern = errors.New("invalid pattern")

func classEnd(p []rune, i int) (int, error) {
	n := len(p)
	j := i + 1
	if j < n && p[j] == '!' {
		j++
	}
	first := true
	for j < n {
		c := p[j]
		if c == ']' && !first {
			return j + 1, nil
		}
		first = false
		if c == '\\' {
			if j+1 >= n {
				return 0, errPattern
			}
			j += 2
		} else {
			j++
		}
	}
	return 0, errPattern
}

func groupEnd(p []rune, i int) (int, []int, error) {
	n := len(p)
	depth := 0
	var commas []int
	j := i
	for j < n {
		c := p[j]
		if c == '\\' {
			if j+1 >= n {
				return 0, nil, errPattern
			}
			j += 2
			continue
		}
		if c == '[' {
			e, err := classEnd(p, j)
			if err != nil {
				return 0, nil, err
			}
			j = e
			continue
		}
		if c == '{' {
			depth++
		} else if c == '}' {
			depth--
			if depth == 0 {
				return j, commas, nil
			}
		} else if c == ',' && depth == 1 {
			commas = append(commas, j)
		}
		j++
	}
	return 0, nil, errPattern
}

func expand(p []rune, out *[]string) error {
	n := len(p)
	j := 0
	for j < n {
		c := p[j]
		switch c {
		case '\\':
			if j+1 >= n {
				return errPattern
			}
			j += 2
		case '[':
			e, err := classEnd(p, j)
			if err != nil {
				return err
			}
			j = e
		case '{':
			end, commas, err := groupEnd(p, j)
			if err != nil {
				return err
			}
			cuts := append([]int{j}, commas...)
			cuts = append(cuts, end)
			for k := 0; k+1 < len(cuts); k++ {
				a, b := cuts[k], cuts[k+1]
				q := make([]rune, 0, n)
				q = append(q, p[:j]...)
				q = append(q, p[a+1:b]...)
				q = append(q, p[end+1:]...)
				if err := expand(q, out); err != nil {
					return err
				}
			}
			return nil
		default:
			j++
		}
	}
	*out = append(*out, string(p))
	if len(*out) > maxAlternatives {
		return errPattern
	}
	return nil
}

func ExpandBraces(pattern string) ([]string, error) {
	out := []string{}
	if err := expand([]rune(pattern), &out); err != nil {
		return nil, err
	}
	return out, nil
}

type span struct{ lo, hi rune }

type token struct {
	kind  byte // 'l' literal, '?' any, '*' star, 'D' double star, 'c' class
	lit   rune
	neg   bool
	items []span
}

func tokens(p []rune) ([]token, error) {
	var toks []token
	n := len(p)
	i := 0
	for i < n {
		c := p[i]
		switch {
		case c == '\\':
			if i+1 >= n {
				return nil, errPattern
			}
			toks = append(toks, token{kind: 'l', lit: p[i+1]})
			i += 2
		case c == '?':
			toks = append(toks, token{kind: '?'})
			i++
		case c == '*':
			j := i
			for j < n && p[j] == '*' {
				j++
			}
			if j-i >= 2 {
				toks = append(toks, token{kind: 'D'})
			} else {
				toks = append(toks, token{kind: '*'})
			}
			i = j
		case c == '[':
			end, err := classEnd(p, i)
			if err != nil {
				return nil, err
			}
			j := i + 1
			neg := false
			if p[j] == '!' {
				neg = true
				j++
			}
			var items []span
			first := true
			for j < end-1 || (first && j < end) {
				if p[j] == ']' && !first {
					break
				}
				first = false
				lo := p[j]
				if lo == '\\' {
					lo = p[j+1]
					j += 2
				} else {
					j++
				}
				if j+1 < end && p[j] == '-' && p[j+1] != ']' {
					j++
					hi := p[j]
					if hi == '\\' {
						hi = p[j+1]
						j += 2
					} else {
						j++
					}
					if hi < lo {
						return nil, errPattern
					}
					items = append(items, span{lo, hi})
				} else {
					items = append(items, span{lo, lo})
				}
			}
			toks = append(toks, token{kind: 'c', neg: neg, items: items})
			i = end
		default:
			toks = append(toks, token{kind: 'l', lit: c})
			i++
		}
	}
	return toks, nil
}

func twin(c rune) rune {
	if c >= 'a' && c <= 'z' {
		return c - 32
	}
	if c >= 'A' && c <= 'Z' {
		return c + 32
	}
	return c
}

func inItems(items []span, c rune) bool {
	for _, it := range items {
		if it.lo <= c && c <= it.hi {
			return true
		}
	}
	return false
}

func single(t token, ch rune, ci bool) bool {
	if t.kind == 'l' {
		return ch == t.lit || (ci && twin(ch) == t.lit)
	}
	if ch == '/' {
		return false
	}
	if t.kind == '?' {
		return true
	}
	inside := inItems(t.items, ch)
	if !inside && ci {
		inside = inItems(t.items, twin(ch))
	}
	return inside != t.neg
}

func match(toks []token, s []rune, ci bool) bool {
	n := len(s)
	nxt := make([]bool, n+1)
	nxt[n] = true
	for k := len(toks) - 1; k >= 0; k-- {
		t := toks[k]
		cur := make([]bool, n+1)
		switch t.kind {
		case 'D':
			cur[n] = nxt[n]
			for j := n - 1; j >= 0; j-- {
				cur[j] = nxt[j] || cur[j+1]
			}
		case '*':
			cur[n] = nxt[n]
			for j := n - 1; j >= 0; j-- {
				cur[j] = nxt[j] || (s[j] != '/' && cur[j+1])
			}
		default:
			for j := 0; j < n; j++ {
				cur[j] = nxt[j+1] && single(t, s[j], ci)
			}
		}
		nxt = cur
	}
	return nxt[0]
}

func compile(pattern string) ([][]token, error) {
	alts, err := ExpandBraces(pattern)
	if err != nil {
		return nil, err
	}
	var out [][]token
	for _, a := range alts {
		t, err := tokens([]rune(a))
		if err != nil {
			return nil, err
		}
		out = append(out, t)
	}
	return out, nil
}

func GlobMatch(pattern, text string, ci bool) (bool, error) {
	compiled, err := compile(pattern)
	if err != nil {
		return false, err
	}
	s := []rune(text)
	for _, t := range compiled {
		if match(t, s, ci) {
			return true, nil
		}
	}
	return false, nil
}

func FilterNames(pattern string, names []string, ci bool) ([]int64, error) {
	compiled, err := compile(pattern)
	if err != nil {
		return nil, err
	}
	out := []int64{}
	for i, name := range names {
		s := []rune(name)
		for _, t := range compiled {
			if match(t, s, ci) {
				out = append(out, int64(i))
				break
			}
		}
	}
	return out, nil
}

func LiteralPrefix(pattern string) string {
	for i, c := range pattern {
		switch c {
		case '*', '?', '[', '{', '\\':
			return pattern[:i]
		}
	}
	return pattern
}

func IsValid(pattern string) bool {
	_, err := compile(pattern)
	return err == nil
}

