_MAX_ALTERNATIVES = 256


def _class_end(p, i):
    """p[i] == '['. Returns the index just after the closing ']' of the class that starts here."""
    n = len(p)
    j = i + 1
    if j < n and p[j] == "!":
        j += 1
    first = True
    while j < n:
        c = p[j]
        if c == "]" and not first:
            return j + 1
        first = False
        if c == "\\":
            if j + 1 >= n:
                raise ValueError("trailing backslash")
            j += 2
        else:
            j += 1
    raise ValueError("unclosed class")


def _group_end(p, i):
    """p[i] == '{'. Returns (index of the matching '}', indices of the top-level commas)."""
    n = len(p)
    depth = 0
    commas = []
    j = i
    while j < n:
        c = p[j]
        if c == "\\":
            if j + 1 >= n:
                raise ValueError("trailing backslash")
            j += 2
            continue
        if c == "[":
            j = _class_end(p, j)
            continue
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return j, commas
        elif c == "," and depth == 1:
            commas.append(j)
        j += 1
    raise ValueError("unclosed brace")


def _expand(p, out):
    n = len(p)
    j = 0
    while j < n:
        c = p[j]
        if c == "\\":
            if j + 1 >= n:
                raise ValueError("trailing backslash")
            j += 2
        elif c == "[":
            j = _class_end(p, j)
        elif c == "{":
            end, commas = _group_end(p, j)
            cuts = [j] + commas + [end]
            for a, b in zip(cuts, cuts[1:]):
                _expand(p[:j] + p[a + 1:b] + p[end + 1:], out)
            return
        else:
            j += 1
    out.append(p)
    if len(out) > _MAX_ALTERNATIVES:
        raise ValueError("too many alternatives")


def expand_braces(pattern):
    out = []
    _expand(pattern, out)
    return out


def _tokens(p):
    toks = []
    n = len(p)
    i = 0
    while i < n:
        c = p[i]
        if c == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            toks.append(("lit", p[i + 1]))
            i += 2
        elif c == "?":
            toks.append(("any",))
            i += 1
        elif c == "*":
            j = i
