function twin(c: string): string {
  if (c >= 'a' && c <= 'z') return String.fromCharCode(c.charCodeAt(0) - 32);
  if (c >= 'A' && c <= 'Z') return String.fromCharCode(c.charCodeAt(0) + 32);
  return c;
