_MAX_ALTERNATIVES = 256


def _class_end(p, i):
    """p[i] == '['. Returns the index just after the closing ']' of the class that starts here."""
    n = len(p)
    j = i + 1
    if j < n and p[j] == "!":
        j += 1
    first = True
    while j < n:
        c = p[j]
        if c == "]" and not first:
            return j + 1
        first = False
        if c == "\\":
            if j + 1 >= n:
                raise ValueError("trailing backslash")
            j += 2
        else:
            j += 1
    raise ValueError("unclosed class")


def _group_end(p, i):
    """p[i] == '{'. Returns (index of the matching '}', indices of the top-level commas)."""
    n = len(p)
    depth = 0
    commas = []
    j = i
    while j < n:
        c = p[j]
        if c == "\\":
            if j + 1 >= n:
                raise ValueError("trailing backslash")
            j += 2
            continue
        if c == "[":
            j = _class_end(p, j)
            continue
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return j, commas
        elif c == "," and depth == 1:
            commas.append(j)
        j += 1
    raise ValueError("unclosed brace")


def _expand(p, out):
    n = len(p)
    j = 0
    while j < n:
        c = p[j]
        if c == "\\":
            if j + 1 >= n:
                raise ValueError("trailing backslash")
            j += 2
        elif c == "[":
            j = _class_end(p, j)
        elif c == "{":
            end, commas = _group_end(p, j)
            cuts = [j] + commas + [end]
            for a, b in zip(cuts, cuts[1:]):
                _expand(p[:j] + p[a + 1:b] + p[end + 1:], out)
            return
        else:
            j += 1
    out.append(p)
    if len(out) > _MAX_ALTERNATIVES:
        raise ValueError("too many alternatives")


def expand_braces(pattern):
    out = []
    _expand(pattern, out)
    return out


def _tokens(p):
    toks = []
    n = len(p)
    i = 0
    while i < n:
        c = p[i]
        if c == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            toks.append(("lit", p[i + 1]))
            i += 2
        elif c == "?":
            toks.append(("any",))
            i += 1
        elif c == "*":
            j = i
            while j < n and p[j] == "*":
                j += 1
            toks.append(("dstar",) if j - i >= 2 else ("star",))
            i = j
        elif c == "[":
            end = _class_end(p, i)
            j = i + 1
            neg = False
            if p[j] == "!":
                neg = True
                j += 1
            items = []
            first = True
            while j < end - 1 or (first and j < end):
                if p[j] == "]" and not first:
                    break
                first = False
                lo = p[j]
                if lo == "\\":
                    lo = p[j + 1]
                    j += 2
                else:
                    j += 1
                if j + 1 < end and p[j] == "-" and p[j + 1] != "]":
                    j += 1
                    hi = p[j]
                    if hi == "\\":
                        hi = p[j + 1]
                        j += 2
                    else:
                        j += 1
                    if ord(hi) < ord(lo):
                        raise ValueError("reversed range")
                    items.append((ord(lo), ord(hi)))
                else:
                    items.append((ord(lo), ord(lo)))
            toks.append(("class", neg, items))
            i = end
        else:
            toks.append(("lit", c))
            i += 1
    return toks


def _twin(c):
    if "a" <= c <= "z":
        return chr(ord(c) - 32)
    if "A" <= c <= "Z":
        return chr(ord(c) + 32)
    return c


def _single(tok, ch, ci):
    kind = tok[0]
    if kind == "lit":
        return ch == tok[1] or (ci and _twin(ch) == tok[1])
    if ch == "/":
        return False
    if kind == "any":
        return True
    inside = any(lo <= ord(ch) <= hi for lo, hi in tok[2])
    if not inside and ci:
        t = _twin(ch)
        inside = any(lo <= ord(t) <= hi for lo, hi in tok[2])
    return inside != tok[1]


def _match(tokens, s, ci):
    n = len(s)
    nxt = [False] * (n + 1)
    nxt[n] = True
    for tok in reversed(tokens):
        cur = [False] * (n + 1)
        if tok[0] == "dstar":
            cur[n] = nxt[n]
            for j in range(n - 1, -1, -1):
                cur[j] = nxt[j] or cur[j + 1]
        elif tok[0] == "star":
            cur[n] = nxt[n]
            for j in range(n - 1, -1, -1):
                cur[j] = nxt[j] or (s[j] != "/" and cur[j + 1])
        else:
            for j in range(n):
                cur[j] = nxt[j + 1] and _single(tok, s[j], ci)
        nxt = cur
    return nxt[0]


def _compile(pattern):
    return [_tokens(alt) for alt in expand_braces(pattern)]


def glob_match(pattern, text, ci):
    compiled = _compile(pattern)
    chars = list(text)
    return any(_match(t, chars, ci) for t in compiled)


def filter_names(pattern, names, ci):
    compiled = _compile(pattern)
    return [i for i, name in enumerate(names) if any(_match(t, list(name), ci) for t in compiled)]


def literal_prefix(pattern):
    for i, c in enumerate(pattern):
        if c in "*?[{\\":
            return pattern[:i]
    return pattern


def is_valid(pattern):
    try:
        _compile(pattern)
        return True
    except ValueError:
        return False

